using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
 public sealed class WardrobeCheckpointTests
 {
  static WardrobeOutfit Look(int model=-1667301416,int drawable=5)=>new WardrobeOutfit{Id="saved",Name="Kit",Model=model,Components=WardrobeRules.ComponentSlots.Select(s=>new WardrobePiece{Slot=s,Drawable=drawable,Texture=1}).ToList(),Props=WardrobeRules.PropSlots.Select(s=>new WardrobePiece{Slot=s,Drawable=-1}).ToList()};
  static CharacterCard Card()=>new CharacterCard{Id="RP_1234567890abcdef",Name="Saved",Model="mp_f_freemode_01",BaseFace=new FaceHeritage{ShapeFirst=0,ShapeSecond=21,SkinFirst=0,SkinSecond=21},ApplyPending=true};
  static CharacterBody Body()=>new CharacterBody{Model=-1667301416,Health=200,MaxHealth=200,SelectedWeapon=CharacterRules.Unarmed,Components=Enumerable.Range(0,12).Select(s=>new WardrobePiece{Slot=s}).ToList(),Props=WardrobeRules.PropSlots.Select(s=>new WardrobePiece{Slot=s,Drawable=-1}).ToList()};
  static bool Equip(WalletData w,WardrobeOutfit look,string id="equip",Action save=null)=>WardrobeTransactions.Equip(w,look,id,save??(()=>{}),out _);
  [Theory][InlineData(true,true,false,false,false,500,false)][InlineData(true,true,true,false,false,500,false)][InlineData(false,true,false,true,false,500,true)][InlineData(false,true,true,false,false,500,true)][InlineData(true,false,true,true,false,500,true)][InlineData(true,true,true,true,true,500,true)][InlineData(true,true,true,true,false,10000,true)][InlineData(true,true,false,false,false,9999,false)]
  public void BriefCameraOrMenuInterruptionAfterModelChangeMustNotAbandonBodyCheckpoint(bool swapped,bool same,bool safe,bool visible,bool cancelled,uint elapsed,bool interrupted)=>Assert.Equal(interrupted,CharacterRules.AppearanceInterrupted(swapped,same,safe,visible,cancelled,elapsed));
  [Fact] public void LegacyPendingBodyNullAndZeroIndexOutfitRemainReadableWithoutInventingClothes(){var c=Card();var w=new WalletData{Wardrobe=new WardrobeData()};w.Wardrobe.Outfits.Add(Look(drawable:0));Assert.True(c.Valid);Assert.True(w.Wardrobe.Valid);Assert.Null(WardrobeTransactions.Equipped(w.Wardrobe,-1667301416));Assert.False(WardrobeTransactions.PreferEquipped(null,c));Assert.True(c.ApplyPending);Assert.Null(c.Body);}
  [Fact] public void ConfirmedLibrarySaveAndEquippedStateCommitTogether(){var w=new WalletData{Cash=186,Bank=10};var look=Look();int writes=0;Assert.True(WardrobeTransactions.Save(w,WardrobeDefaults.Load(),look,false,"save",()=>{writes++;Assert.Single(w.Wardrobe.Outfits);Assert.Equal(1,Assert.Single(w.Wardrobe.Equipped).Revision);},out _,true));Assert.Equal(1,writes);Assert.Equal(186,w.Cash);Assert.Equal(10,w.Bank);Assert.Equal(5,w.Wardrobe.Equipped[0].Components[0].Drawable);Assert.Equal(0,look.Revision);}
  [Fact] public void FailedCombinedSaveRollsBackBothLibraryAndEquippedCheckpoint(){var w=new WalletData{Bank=10};string before=JsonConvert.SerializeObject(w);Assert.Throws<IOException>(()=>WardrobeTransactions.Save(w,WardrobeDefaults.Load(),Look(),false,"save",()=>throw new IOException(),out _,true));Assert.Equal(before,JsonConvert.SerializeObject(w));}
  [Fact] public void WearingDoesNotChangeLibraryAndSurvivesImmediateReloadWithoutCharacterAutosave(){var w=new WalletData();WardrobeTransactions.Save(w,WardrobeDefaults.Load(),Look(),false,"save",()=>{},out _);string library=JsonConvert.SerializeObject(w.Wardrobe.Outfits);Assert.True(Equip(w,w.Wardrobe.Outfits[0]));w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.Equal(library,JsonConvert.SerializeObject(w.Wardrobe.Outfits));Assert.True(WardrobeTransactions.PreferEquipped(WardrobeTransactions.Equipped(w.Wardrobe,-1667301416),Card()));}
  [Fact] public void EquipReplayDoesNotIncreaseRevisionOrSaveTwice(){var w=new WalletData();Assert.True(Equip(w,Look()));Assert.True(Equip(w,Look(drawable:9),save:()=>throw new Exception()));Assert.Equal(1,w.Wardrobe.Equipped[0].Revision);Assert.Equal(5,w.Wardrobe.Equipped[0].Components[0].Drawable);}
  [Fact] public void IOFailureKeepsPreviousActiveLookAndRevision(){var w=new WalletData();Equip(w,Look());string before=JsonConvert.SerializeObject(w);Assert.Throws<IOException>(()=>Equip(w,Look(drawable:9),"second",()=>throw new IOException()));Assert.Equal(before,JsonConvert.SerializeObject(w));}
  [Fact] public void NewerWardrobeCheckpointWinsOverOlderBodyButLaterBodySaveWinsOverStaleOutfit(){var w=new WalletData();Equip(w,Look());var c=Card();c.Body=Body();c.ApplyPending=false;var checkpoint=WardrobeTransactions.Equipped(w.Wardrobe,c.Body.Model);Assert.True(WardrobeTransactions.PreferEquipped(checkpoint,c));c.BodyClothingRevision=checkpoint.Revision;Assert.False(WardrobeTransactions.PreferEquipped(checkpoint,c));Equip(w,Look(drawable:8),"new");Assert.True(WardrobeTransactions.PreferEquipped(WardrobeTransactions.Equipped(w.Wardrobe,c.Body.Model),c));}
  [Fact] public void ModelsAndProfilesNeverShareEquippedState(){var a=new WalletData();var b=new WalletData();Equip(a,Look());Equip(a,Look(1885233650),"male");Assert.Equal(2,a.Wardrobe.Equipped.Count);Assert.Null(b.Wardrobe);Assert.False(WardrobeTransactions.PreferEquipped(WardrobeTransactions.Equipped(a.Wardrobe,1885233650),Card()));}
  [Fact] public void DeleteOrRenameLibraryDoesNotEraseCurrentlyWornCheckpoint(){var w=new WalletData();WardrobeTransactions.Save(w,WardrobeDefaults.Load(),Look(),false,"save",()=>{},out _,true);WardrobeTransactions.Rename(w,"saved","New name","rename",()=>{},out _);WardrobeTransactions.Delete(w,"saved","delete",()=>{},out _);Assert.Empty(w.Wardrobe.Outfits);Assert.Single(w.Wardrobe.Equipped);}
  [Fact] public void UnknownWalletEquippedAndPieceMetadataSurvivesNextWear(){var w=new WalletData();Equip(w,Look());var j=JObject.FromObject(w);j["Future"]=1;j["Wardrobe"]["Equipped"][0]["Future"]=2;j["Wardrobe"]["Equipped"][0]["Components"][0]["Future"]=3;w=j.ToObject<WalletData>();Equip(w,Look(drawable:8),"second");var after=JObject.FromObject(w);Assert.Equal(1,(int)after["Future"]);Assert.Equal(2,(int)after["Wardrobe"]["Equipped"][0]["Future"]);Assert.Equal(3,(int)after["Wardrobe"]["Equipped"][0]["Components"][0]["Future"]);Assert.Equal(2,w.Wardrobe.Equipped[0].Revision);}
  [Fact] public void RevisionOverflowRefusesWholeTransactionWithoutChangingLibrary(){var w=new WalletData();Equip(w,Look());w.Wardrobe.Equipped[0].Revision=long.MaxValue;string before=JsonConvert.SerializeObject(w);Assert.False(WardrobeTransactions.Save(w,WardrobeDefaults.Load(),Look(),false,"save",()=>throw new Exception(),out _,true));Assert.Equal(before,JsonConvert.SerializeObject(w));}
  [Fact] public void InvalidCheckpointOrNegativeBodyRevisionCannotSilentlyResetProgress(){var w=new WalletData();Equip(w,Look());w.Wardrobe.Equipped[0].Revision=-1;string before=JsonConvert.SerializeObject(w);Assert.False(Equip(w,Look(),"second"));Assert.Equal(before,JsonConvert.SerializeObject(w));var c=Card();c.BodyClothingRevision=-1;Assert.False(c.Valid);}
  [Fact] public void DrawableValidationRejectsOutOfRangeBeforeAnyTextureLookup(){Assert.False(WardrobeRules.DrawableAvailable(new WardrobePiece{Drawable=5},false,5));Assert.True(WardrobeRules.DrawableAvailable(new WardrobePiece{Drawable=0},false,0));Assert.True(WardrobeRules.DrawableAvailable(new WardrobePiece{Drawable=-1},true,0));Assert.False(WardrobeRules.DrawableAvailable(new WardrobePiece{Drawable=-2},true,0));}
  [Fact] public void NamingChangeComparisonDetectsResetInsteadOfSavingZeroKit(){var before=Look();var after=Look(drawable:0);Assert.False(PersonalServiceRules.SameClothes(before,after));Assert.True(PersonalServiceRules.SameClothes(before,JsonConvert.DeserializeObject<WardrobeOutfit>(JsonConvert.SerializeObject(before))));}
 }
}
